    .collect(Collectors.groupingBy(Trade::getSymbol, Collectors.counting()));
// {"RELIANCE": 2, "TCS": 1, "HDFC": 1}

// ═══ DOWNSTREAM: summing ═══
Map<String, Double> totalBySymbol = trades.stream()
    .collect(Collectors.groupingBy(Trade::getSymbol,
        Collectors.summingDouble(t -> t.getAmount().doubleValue())));

// ═══ DOWNSTREAM: mapping to different type ═══
Map<String, List<String>> idsBySymbol = trades.stream()
    .collect(Collectors.groupingBy(Trade::getSymbol,
        Collectors.mapping(Trade::getTradeId, Collectors.toList())));
// {"RELIANCE": ["TRD-001", "TRD-006"], "TCS": ["TRD-002"]}

// ═══ DOWNSTREAM: maxBy ═══
Map<String, Optional<Trade>> largestBySymbol = trades.stream()
    .collect(Collectors.groupingBy(Trade::getSymbol,
        Collectors.maxBy(Comparator.comparing(Trade::getAmount))));

// ═══ MULTI-LEVEL: group by symbol, then by side ═══
Map<String, Map<String, List<Trade>>> bySymbolThenSide = trades.stream()
    .collect(Collectors.groupingBy(Trade::getSymbol,
        Collectors.groupingBy(Trade::getSide)));
// {"RELIANCE": {"BUY": [T1], "SELL": [T6]}, "TCS": {"BUY": [T2]}}

// ═══ SORTED KEYS: TreeMap ═══
