package com.bank.grouping.model;

import java.math.BigDecimal;

public record Trade(String tradeId, String accountId, String symbol, String side,
                    BigDecimal amount, String status) {
    public boolean isSettled() { return "SETTLED".equals(status); }

    public String getAmountRange() {
        if (amount.compareTo(new BigDecimal("50000")) < 0) return "SMALL (<50K)";
        if (amount.compareTo(new BigDecimal("200000")) < 0) return "MEDIUM (50K-200K)";
        return "LARGE (>200K)";
    }
}
