package com.bank.grouping.service;

import com.bank.grouping.dto.GroupingReport;
import com.bank.grouping.model.Trade;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.util.*;
import java.util.stream.Collectors;

@Service
@Slf4j
public class GroupingService {

    private final List<Trade> trades = List.of(
        new Trade("TRD-001", "SAV2001", "RELIANCE", "BUY",  new BigDecimal("245050"), "SETTLED"),
        new Trade("TRD-002", "SAV2001", "TCS",      "BUY",  new BigDecimal("176000"), "SETTLED"),
        new Trade("TRD-003", "CUR3001", "HDFC",     "SELL", new BigDecimal("330150"), "PENDING"),
        new Trade("TRD-004", "SAV2001", "INFY",     "BUY",  new BigDecimal("222037"), "SETTLED"),
        new Trade("TRD-005", "CUR3001", "WIPRO",    "SELL", new BigDecimal("33664"),  "SETTLED"),
        new Trade("TRD-006", "SAV2001", "RELIANCE", "SELL", new BigDecimal("123750"), "SETTLED"),
        new Trade("TRD-007", "CUR3001", "TCS",      "BUY",  new BigDecimal("88750"),  "FAILED")
    );

    public GroupingReport generateReport() {

        // ═══ 1. SINGLE-LEVEL: count per symbol ═══
        Map<String, Long> countBySymbol = trades.stream()
            .collect(Collectors.groupingBy(Trade::symbol, TreeMap::new, Collectors.counting()));
        log.info("Count by symbol: {}", countBySymbol);

        // ═══ 2. MULTI-LEVEL: symbol → side → count ═══
        Map<String, Map<String, Long>> bySymbolThenSide = trades.stream()
            .collect(Collectors.groupingBy(Trade::symbol,
                Collectors.groupingBy(Trade::side, Collectors.counting())));
        log.info("By symbol then side: {}", bySymbolThenSide);

        // ═══ 3. DOWNSTREAM summingBigDecimal: total amount per account ═══
        Map<String, BigDecimal> totalByAccount = trades.stream()
            .collect(Collectors.groupingBy(Trade::accountId,
                Collectors.reducing(BigDecimal.ZERO, Trade::amount, BigDecimal::add)));
        log.info("Total by account: {}", totalByAccount);

        // ═══ 4. CUSTOM CLASSIFIER: group by amount range ═══
        Map<String, Long> byRange = trades.stream()
            .collect(Collectors.groupingBy(Trade::getAmountRange, Collectors.counting()));
        log.info("By amount range: {}", byRange);

        // ═══ 5. PARTITIONING: settled vs unsettled ═══
        Map<Boolean, Long> settledVsNot = trades.stream()
            .collect(Collectors.partitioningBy(Trade::isSettled, Collectors.counting()));
        log.info("Settled vs unsettled: {}", settledVsNot);

        // ═══ 6. DOWNSTREAM mapping: trade IDs per symbol ═══
        Map<String, List<String>> idsBySymbol = trades.stream()
            .collect(Collectors.groupingBy(Trade::symbol,
                Collectors.mapping(Trade::tradeId, Collectors.toList())));
        log.info("Trade IDs by symbol: {}", idsBySymbol);

        // ═══ 7. DOWNSTREAM maxBy: largest trade per symbol ═══
        Map<String, Optional<String>> largestBySymbol = trades.stream()
            .collect(Collectors.groupingBy(Trade::symbol,
                Collectors.maxBy(Comparator.comparing(Trade::amount))
                    .andThen(opt -> opt.map(Trade::tradeId))));
        // Note: Collector.andThen not available pre-Java 12, use collectingAndThen:
        Map<String, Optional<String>> largestBySymbol2 = trades.stream()
            .collect(Collectors.groupingBy(Trade::symbol,
                Collectors.collectingAndThen(
                    Collectors.maxBy(Comparator.comparing(Trade::amount)),
                    opt -> opt.map(Trade::tradeId))));
        log.info("Largest trade by symbol: {}", largestBySymbol2);

        return new GroupingReport(countBySymbol, bySymbolThenSide, totalByAccount,
            byRange, settledVsNot, idsBySymbol, largestBySymbol2);
    }
}
