package com.bank.grouping.service;

import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.stream.*;
import static org.assertj.core.api.Assertions.*;

class GroupingByTest {

    @Test
    void basicGroupingByProducesMapOfLists() {
        Map<Integer, List<String>> byLength = Stream.of("RELIANCE", "TCS", "HDFC", "INFY")
            .collect(Collectors.groupingBy(String::length));

        assertThat(byLength.get(8)).containsExactly("RELIANCE");
        assertThat(byLength.get(3)).containsExactly("TCS");
        assertThat(byLength.get(4)).containsExactly("HDFC", "INFY");
    }

    @Test
    void groupingByWithCounting() {
        Map<String, Long> counts = Stream.of("BUY", "SELL", "BUY", "BUY", "SELL")
            .collect(Collectors.groupingBy(s -> s, Collectors.counting()));
        assertThat(counts).containsEntry("BUY", 3L).containsEntry("SELL", 2L);
    }

    @Test
    void multiLevelGrouping() {
        record Item(String cat, String sub) {}
        var items = List.of(new Item("A", "X"), new Item("A", "Y"),
            new Item("B", "X"), new Item("A", "X"));

        Map<String, Map<String, Long>> grouped = items.stream()
            .collect(Collectors.groupingBy(Item::cat,
                Collectors.groupingBy(Item::sub, Collectors.counting())));

        assertThat(grouped.get("A").get("X")).isEqualTo(2);
        assertThat(grouped.get("A").get("Y")).isEqualTo(1);
        assertThat(grouped.get("B").get("X")).isEqualTo(1);
    }

    @Test
    void sortedKeysWithTreeMap() {
        Map<String, Long> sorted = Stream.of("TCS", "RELIANCE", "HDFC", "RELIANCE")
            .collect(Collectors.groupingBy(s -> s, TreeMap::new, Collectors.counting()));
        assertThat(new ArrayList<>(sorted.keySet())).containsExactly("HDFC", "RELIANCE", "TCS");
    }

    @Test
    void partitioningByProducesTrueFalseMap() {
        Map<Boolean, List<Integer>> partitioned = Stream.of(780, 580, 650, 490)
            .collect(Collectors.partitioningBy(s -> s >= 650));
        assertThat(partitioned.get(true)).containsExactly(780, 650);
        assertThat(partitioned.get(false)).containsExactly(580, 490);
    }

    @Test
    void collectingAndThenTransformsResult() {
        String csv = Stream.of("RELIANCE", "TCS", "HDFC")
            .collect(Collectors.collectingAndThen(
                Collectors.joining(", "),
                result -> "[" + result + "]"));
        assertThat(csv).isEqualTo("[RELIANCE, TCS, HDFC]");
    }
}
